import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Plus, Search, Eye, Edit, Trash2, Calendar, TrendingUp } from 'lucide-react';
import { API_BASE_URL } from '../../config/api';

function PostsContent({ fetchStats }) {
  const navigate = useNavigate();
  const [posts, setPosts] = useState([]);
  const [filteredPosts, setFilteredPosts] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');

  useEffect(() => {
    fetchPosts();
  }, []);

  const fetchPosts = async () => {
    const token = localStorage.getItem('token');
    
    try {
      const response = await fetch(`${API_BASE_URL}/api/posts/admin/all`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await response.json();
      setPosts(data.posts || []);
      setFilteredPosts(data.posts || []);
    } catch (error) {
      console.error('Error fetching posts:', error);
    }
  };

  // Filtrar posts quando mudar pesquisa ou filtros
  useEffect(() => {
    let result = posts;

    // Filtro de pesquisa
    if (searchTerm) {
      result = result.filter(post =>
        post.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        post.excerpt?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        post.category?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Filtro de categoria
    if (filterCategory !== 'all') {
      result = result.filter(post => post.category === filterCategory);
    }

    // Filtro de status
    if (filterStatus !== 'all') {
      result = result.filter(post => post.status === filterStatus);
    }

    setFilteredPosts(result);
  }, [searchTerm, filterCategory, filterStatus, posts]);

  // Obter categorias únicas
  const categories = [...new Set(posts.map(post => post.category).filter(Boolean))];

  const handleDelete = async (postId) => {
    if (!window.confirm('Tem certeza que deseja excluir este post?')) return;

    const token = localStorage.getItem('token');
    try {
      const response = await fetch(`${API_BASE_URL}/api/posts/${postId}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (response.ok) {
        fetchPosts();
        if (fetchStats) fetchStats();
      }
    } catch (error) {
      console.error('Error deleting post:', error);
    }
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('pt-PT');
  };

  return (
    <div className="posts-content-new">
      <div className="content-header-new">
        {/* Barra de Pesquisa */}
        <div className="search-box">
          <Search size={20} />
          <input
            type="text"
            placeholder="Pesquisar posts..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          {searchTerm && (
            <span className="results-count-inline">
              {filteredPosts.length} resultado{filteredPosts.length !== 1 ? 's' : ''}
            </span>
          )}
        </div>

        <button 
          className="create-button-new"
          onClick={() => navigate('/admin/posts/new')}
        >
          <Plus size={20} />
          Novo Post
        </button>
      </div>

      <div className="table-container-new">
        <table className="admin-table-new">
          <thead>
            <tr>
              <th>Título</th>
              <th>Categoria</th>
              <th>Status</th>
              <th>Visualizações</th>
              <th>Data</th>
              <th>Ações</th>
            </tr>
          </thead>
          <tbody>
            {filteredPosts.map(post => (
              <tr key={post.id}>
                <td>{post.title}</td>
                <td>{post.category}</td>
                <td>
                  <span className={`status-badge ${post.status}`}>
                    {post.status === 'published' ? 'Publicado' : 'Rascunho'}
                  </span>
                </td>
                <td>{post.views}</td>
                <td>{formatDate(post.created_at)}</td>
                <td>
                  <div className="action-buttons">
                    <button 
                      className="action-btn edit"
                      onClick={() => navigate(`/admin/posts/edit/${post.id}`)}
                    >
                      <Edit size={16} />
                    </button>
                    <button 
                      className="action-btn delete"
                      onClick={() => handleDelete(post.id)}
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default PostsContent;
